1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const INSURANCE_VALUE_BY_ITEM_TYPE = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	} as const satisfies Record<InsurableItemType, number>;
22	
23	const DEDUCTIBLE_PER_DAMAGE = 100;
24	
25	// Distinct from HIGH_ENCHANTMENT_THRESHOLD: that one raises the premium at
26	// level 5, this one halves the reimbursement at level 8.
27	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	
29	const REIMBURSEMENT_ENCHANTMENT_RATE = 0.5;
30	
31	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
32	
33	const BLOCK_SIZE = 3;
34	
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const CURSE_SURCHARGE_RATE = 0.5;
38	
39	const HIGH_ENCHANTMENT_THRESHOLD = 5;
40	
41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
42	
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	
49	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
50	
51	export type QuoteResult = { premium: number };
52	
53	export type ClaimResult = { payout: number; remainingCap: number };
54	
55	export type ScenarioResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioOutcome = { results: ScenarioResult[] };
58	
59	type Item = {
60	  type: InsurableItemType;
61	  cursed?: boolean;
62	  enchantment?: number;
63	};
64	
65	type Customer = { yearsWithMHPCO: number };
66	
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type ClaimStep = {
72	  op: "claim";
73	  policy: number;
74	  incident: { cause: string; damages: Damage[] };
75	};
76	
77	type Step = QuoteStep | ClaimStep;
78	
79	export type Scenario = { customer: Customer; steps: Step[] };
80	
81	// One rounding rule, stated once: a fractional amount always settles in the
82	// MHPCO's favour, so the direction follows the direction the money moves.
83	// Money the customer pays rounds up; money the customer receives rounds down.
84	const roundAmountCustomerPays = Math.ceil;
85	const roundAmountCustomerReceives = Math.floor;
86	
87	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
88	  const counts = new Map<InsurableItemType, number>();
89	
90	  for (const item of items) {
91	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
92	  }
93	
94	  return counts;
95	};
96	
97	// Exactly 3 alike components form a building block at a special base premium.
98	const basePremiumForAlikeItems = (
99	  type: InsurableItemType,
100	  count: number,
101	): number =>
102	  count === BLOCK_SIZE
103	    ? BLOCK_BASE_PREMIUM
104	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
105	
106	const basePremiumOf = (items: Item[]): number =>
107	  [...countByItemType(items)]
108	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
109	    .reduce((total, premium) => total + premium, 0);
110	
111	const ownBasePremiumOf = (item: Item): number =>
112	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
113	
114	// Item-specific modifiers apply to the affected item's own base premium,
115	// not to the policy total.
116	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
117	
118	const CURSE_MODIFIER: ItemModifier = {
119	  appliesTo: (item) => item.cursed === true,
120	  rate: CURSE_SURCHARGE_RATE,
121	};
122	
123	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
124	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
125	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
126	};
127	
128	const ITEM_MODIFIERS: ItemModifier[] = [
129	  CURSE_MODIFIER,
130	  HIGH_ENCHANTMENT_MODIFIER,
131	];
132	
133	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
134	  items
135	    .filter(modifier.appliesTo)
136	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
137	
138	// Item modifiers accumulate: an item matching several of them pays each
139	// surcharge on its own base premium.
140	const itemSurchargesOf = (items: Item[]): number =>
141	  ITEM_MODIFIERS.reduce(
142	    (total, modifier) => total + itemSurchargeOf(items, modifier),
143	    0,
144	  );
145	
146	// Policy-wide modifiers are computed from the policy base premium, so the
147	// first insurance surcharge is 10 % of the base — not of base plus curse.
148	// A modifier's rate is signed: surcharges are positive, discounts negative.
149	type PolicyContext = { customer: Customer; precedingQuotes: number };
150	
151	type PolicyModifier = {
152	  appliesTo: (context: PolicyContext) => boolean;
153	  rate: number;
154	};
155	
156	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
157	  appliesTo: () => true,
158	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
159	};
160	
161	const LOYALTY_MODIFIER: PolicyModifier = {
162	  appliesTo: ({ customer }) =>
163	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
164	  rate: -LOYALTY_DISCOUNT_RATE,
165	};
166	
167	// Each item in a quote counts as a first insurance regardless of customer
168	// history, so this discount stacks with the first insurance surcharge.
169	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
170	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
171	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
172	};
173	
174	const POLICY_MODIFIERS: PolicyModifier[] = [
175	  FIRST_INSURANCE_MODIFIER,
176	  LOYALTY_MODIFIER,
177	  FOLLOW_UP_CONTRACT_MODIFIER,
178	];
179	
180	// Policy modifiers accumulate: each applicable one is computed on the same
181	// policy base premium, never compounded on top of another.
182	const policyAdjustmentOf = (
183	  basePremium: number,
184	  context: PolicyContext,
185	): number =>
186	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
187	    (total, modifier) => total + basePremium * modifier.rate,
188	    0,
189	  );
190	
191	const quotePremium = (items: Item[], context: PolicyContext): number => {
192	  const basePremium = basePremiumOf(items);
193	
194	  return roundAmountCustomerPays(
195	    basePremium +
196	      itemSurchargesOf(items) +
197	      policyAdjustmentOf(basePremium, context) +
198	      PROCESSING_FEE,
199	  );
200	};
201	
202	const insuranceSumOf = (items: Item[]): number =>
203	  items.reduce(
204	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
205	    0,
206	  );
207	
208	// A reimbursement clause reduces the damage amount to a fraction of itself,
209	// keyed on the insured item's attributes — which the damage entry does not
210	// carry, it names only the item type. Same {appliesTo, rate} shape as
211	// ItemModifier, but the rate is a share of the damage rather than a surcharge
212	// on a base premium. Only one clause exists so far, so the selection below is
213	// a plain conditional; a second clause will need a rule for which one wins.
214	type ReimbursementClause = { appliesTo: (item: Item) => boolean; rate: number };
215	
216	const HIGH_ENCHANTMENT_CLAUSE: ReimbursementClause = {
217	  appliesTo: (item) =>
218	    (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD,
219	  rate: REIMBURSEMENT_ENCHANTMENT_RATE,
220	};
221	
222	const FULL_REIMBURSEMENT_RATE = 1;
223	
224	const reimbursementRateFor = (insuredItem: Item): number =>
225	  HIGH_ENCHANTMENT_CLAUSE.appliesTo(insuredItem)
226	    ? HIGH_ENCHANTMENT_CLAUSE.rate
227	    : FULL_REIMBURSEMENT_RATE;
228	
229	const reimbursementFor = (damageAmount: number, insuredItem: Item): number =>
230	  damageAmount * reimbursementRateFor(insuredItem);
231	
232	// Each damage entry is a distinct damaged item, so it claims one insured item
233	// of that type and no other entry may claim the same one.
234	const claimInsuredItem = (
235	  damage: Damage,
236	  unclaimedItems: Item[],
237	): { insuredItem: Item; remainingItems: Item[] } => {
238	  const index = unclaimedItems.findIndex(
239	    (item) => item.type === damage.itemType,
240	  );
241	
242	  if (index === -1) {
243	    throw new Error(
244	      `the policy does not cover a damaged ${damage.itemType}`,
245	    );
246	  }
247	
248	  return {
249	    insuredItem: unclaimedItems[index],
250	    remainingItems: unclaimedItems.filter((_, at) => at !== index),
251	  };
252	};
253	
254	// Rejecting a damage entry is kept apart from pricing it, so payoutForDamage
255	// below is purely a calculation and its name stays true. Zero is a valid
256	// amount: the spec rejects only negative ones.
257	//
258	// All four throw sites (this one, rejectInvalidDamage, claimInsuredItem and
259	// policyCreatedBy) raise a plain Error. A named error type has been
260	// reconsidered at each and deferred again: no consumer discriminates between
261	// them — every test asserts a bare .toThrow() or matches the message text, and
262	// all four mean the same thing, "the submitted scenario is invalid". The CLI is
263	// the first real consumer; introduce a type when a CLI test demands different
264	// handling per cause, not merely a non-zero exit.
265	// The MHPCO insures only the item types on its price list.
266	const rejectUninsurableItem = (item: Item): void => {
267	  if (!(item.type in BASE_PREMIUM_BY_ITEM_TYPE)) {
268	    throw new Error(`the MHPCO does not insure a ${item.type}`);
269	  }
270	};
271	
272	const rejectInvalidDamage = (damage: Damage): void => {
273	  if (damage.amount < 0) {
274	    throw new Error(
275	      `the damage to the ${damage.itemType} is a negative amount`,
276	    );
277	  }
278	};
279	
280	// A deductible applies per damage event, i.e. once per damaged item.
281	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
282	  reimbursementFor(damage.amount, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
283	
284	// Each damage entry carries its own deductible, so this is a plain sum over
285	// the entries. The policy's cap is applied by the caller.
286	const desiredPayoutForIncident = (
287	  damages: Damage[],
288	  insuredItems: Item[],
289	): number =>
290	  damages.reduce(
291	    ({ total, unclaimedItems }, damage) => {
292	      rejectInvalidDamage(damage);
293	
294	      const { insuredItem, remainingItems } = claimInsuredItem(
295	        damage,
296	        unclaimedItems,
297	      );
298	
299	      return {
300	        total: total + payoutForDamage(damage, insuredItem),
301	        unclaimedItems: remainingItems,
302	      };
303	    },
304	    { total: 0, unclaimedItems: insuredItems },
305	  ).total;
306	
307	// A policy is created by a quote step; claims draw down its remaining cap.
308	// The insured items are retained because payout clauses depend on them.
309	type Policy = { remainingCap: number; items: Item[] };
310	
311	const capFor = (items: Item[]): number =>
312	  insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
313	
314	// A claim quotes its policy by the index of the step that created it, so
315	// policies are keyed by that index rather than collected in a list.
316	type ScenarioState = {
317	  customer: Customer;
318	  policiesByStep: Map<number, Policy>;
319	  precedingQuotes: number;
320	  results: ScenarioResult[];
321	};
322	
323	const initialState = (customer: Customer): ScenarioState => ({
324	  customer,
325	  policiesByStep: new Map(),
326	  precedingQuotes: 0,
327	  results: [],
328	});
329	
330	// Each step handler folds the state forward: it reads what earlier steps
331	// established and returns the state the following steps will see.
332	const applyQuote = (
333	  state: ScenarioState,
334	  step: QuoteStep,
335	  stepIndex: number,
336	): ScenarioState => {
337	  const { customer, precedingQuotes } = state;
338	
339	  step.items.forEach(rejectUninsurableItem);
340	
341	  const premium = quotePremium(step.items, { customer, precedingQuotes });
342	
343	  return {
344	    ...state,
345	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, {
346	      remainingCap: capFor(step.items),
347	      items: step.items,
348	    }),
349	    precedingQuotes: precedingQuotes + 1,
350	    results: [...state.results, { premium }],
351	  };
352	};
353	
354	// A resolving guard rather than a void `reject*` one: the other validators
355	// check a value the caller already holds, this one produces the value. Hence
356	// the noun name — it reads as a lookup that refuses to fail silently.
357	const policyCreatedBy = (
358	  stepIndex: number,
359	  policiesByStep: Map<number, Policy>,
360	): Policy => {
361	  const policy = policiesByStep.get(stepIndex);
362	
363	  if (policy === undefined) {
364	    throw new Error(`no policy was created by step ${stepIndex}`);
365	  }
366	
367	  return policy;
368	};
369	
370	const applyClaim = (state: ScenarioState, step: ClaimStep): ScenarioState => {
371	  const policy = policyCreatedBy(step.policy, state.policiesByStep);
372	
373	  const desiredPayout = desiredPayoutForIncident(
374	    step.incident.damages,
375	    policy.items,
376	  );
377	  // The total payout per policy is capped, so a claim can pay out no more
378	  // than the cap the policy has left.
379	  const payout = roundAmountCustomerReceives(
380	    Math.min(desiredPayout, policy.remainingCap),
381	  );
382	  const remainingCap = policy.remainingCap - payout;
383	
384	  return {
385	    ...state,
386	    policiesByStep: new Map(state.policiesByStep).set(step.policy, {
387	      ...policy,
388	      remainingCap,
389	    }),
390	    results: [...state.results, { payout, remainingCap }],
391	  };
392	};
393	
394	const applyStep = (
395	  state: ScenarioState,
396	  step: Step,
397	  stepIndex: number,
398	): ScenarioState =>
399	  step.op === "quote"
400	    ? applyQuote(state, step, stepIndex)
401	    : applyClaim(state, step);
402	
403	const isObject = (value: unknown): value is Record<string, unknown> =>
404	  typeof value === "object" && value !== null;
405	
406	// Each step's envelope — that it is an object naming an operation this domain
407	// runs, and carries the field that operation needs. Only the envelope: an
408	// item's `type` or a damage's `amount` is still the domain's to judge, so those
409	// keep producing their own descriptions. The line sits exactly where a value
410	// would otherwise be dereferenced blind (`step.items.forEach`, `step.op`) and
411	// surface a JavaScript internal instead of a description of the input.
412	const parseQuoteStep = (
413	  step: Record<string, unknown>,
414	  stepIndex: number,
415	): QuoteStep => {
416	  if (!Array.isArray(step.items)) {
417	    throw new Error(`the quote at step ${stepIndex} needs an array of items`);
418	  }
419	
420	  return { op: "quote", items: step.items };
421	};
422	
423	const parseClaimStep = (
424	  step: Record<string, unknown>,
425	  stepIndex: number,
426	): ClaimStep => {
427	  if (typeof step.policy !== "number") {
428	    throw new Error(`the claim at step ${stepIndex} needs a policy number`);
429	  }
430	
431	  if (!isObject(step.incident) || !Array.isArray(step.incident.damages)) {
432	    throw new Error(
433	      `the claim at step ${stepIndex} needs an incident with an array of damages`,
434	    );
435	  }
436	
437	  return {
438	    op: "claim",
439	    policy: step.policy,
440	    incident: {
441	      cause: String(step.incident.cause),
442	      damages: step.incident.damages,
443	    },
444	  };
445	};
446	
447	const parseStep = (step: unknown, stepIndex: number): Step => {
448	  if (!isObject(step)) {
449	    throw new Error(`step ${stepIndex} must be an object`);
450	  }
451	
452	  if (step.op === "quote") return parseQuoteStep(step, stepIndex);
453	  if (step.op === "claim") return parseClaimStep(step, stepIndex);
454	
455	  throw new Error(
456	    `step ${stepIndex} must be a quote or a claim, not ${JSON.stringify(step.op)}`,
457	  );
458	};
459	
460	// The wire boundary: stdin carries arbitrary JSON, so the scenario shape is
461	// checked here rather than asserted. The check runs only as deep as the shape
462	// the domain relies on structurally; the values inside are the domain's to
463	// reject, with its own wording.
464	export const parseScenario = (input: unknown): Scenario => {
465	  if (!isObject(input)) {
466	    throw new Error("the scenario must be an object");
467	  }
468	
469	  const { customer, steps } = input;
470	
471	  if (!isObject(customer) || typeof customer.yearsWithMHPCO !== "number") {
472	    throw new Error(
473	      "the scenario needs a customer with a numeric yearsWithMHPCO",
474	    );
475	  }
476	
477	  if (!Array.isArray(steps)) {
478	    throw new Error("the scenario needs an array of steps");
479	  }
480	
481	  return {
482	    customer: { yearsWithMHPCO: customer.yearsWithMHPCO },
483	    steps: steps.map(parseStep),
484	  };
485	};
486	
487	export const runScenario = ({ customer, steps }: Scenario): ScenarioOutcome => {
488	  const { results } = steps.reduce(applyStep, initialState(customer));
489	
490	  return { results };
491	};
