1	import { describe, it, expect } from "vitest";
2	import { parseScenario, runScenario } from "./claim-office.js";
3	
4	// These tests submit scenarios the way a caller does: as untyped data that has
5	// to cross the wire boundary before the domain sees it. The literals below
6	// cannot be typed as `Scenario` directly — they carry fields the domain ignores
7	// (`material`) and, in the error cases, deliberately invalid ones
8	// (`type: "broomstick"`) that only a runtime check can reject. So each scenario
9	// goes through the real parseScenario rather than a cast.
10	const submit = (scenario: unknown) => runScenario(parseScenario(scenario));
11	
12	describe("MHPCO Claim Office", () => {
