100	    expect(submit(scenario)).toEqual({ results: [{ premium: 33 }] });
101	  });
102	  it("2 runes → 50 G base premium, no block (+10 % first insurance +5 G fee = 60 G)", () => {
103	    const scenario = {
104	      customer: { yearsWithMHPCO: 0 },
105	      steps: [
106	        { op: "quote", items: [{ type: "rune" }, { type: "rune" }] },
107	      ],
108	    };
109	
110	    expect(submit(scenario)).toEqual({ results: [{ premium: 60 }] });
111	  });
112	  it("3 runes → 60 G base premium, block applies (+10 % first insurance +5 G fee = 71 G)", () => {
